      "concept_name": {
        "text": "AI agents can make decisions and take actions autonomously",
        "refs": ["Q0000", "Q0001"],
        "claims": [
          {
            "text": "AI agents can make decisions and take actions without needing detailed instructions",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0000", "Q0001"],
            "related_refs": []
          }
        ]
      },
      "content": {
        "text": "AI agents can reason through complex tasks, proactively take multi‑step actions to accomplish a goal, and do not require step‑by‑step prompting.",
        "refs": ["Q0001"],
        "claims": [
          {
            "text": "AI agents will figure out a plan and execute it given only a goal",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "explanation_of_mistake",
            "refs": ["Q0001"],
            "related_refs": []
          }
        ]
      },
      "aliases": null
    },
    {
      "concept_name": {
        "text": "Frameworks for building AI agents",
        "refs": ["Q0002", "Q0003", "Q0004"],
        "claims": [
          {
            "text": "Frameworks such as Agno, Google Agent Development Kit, and OpenAI’s Python toolkit can be used to build AI agents",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0002", "Q0003"],
            "related_refs": []
          },
          {
            "text": "Low‑code or no‑code tools such as n8n can also be used to build agentic AI systems",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0004"],
            "related_refs": []
          }
        ]
      },
      "content": {
        "text": "These frameworks provide the necessary components (LLM, memory, tools) to create autonomous agents.",
        "refs": ["Q0002", "Q0003", "Q0004"],
        "claims": [
          {
            "text": "Frameworks supply LLMs, memory stores, and tool integrations for autonomous agents",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "explanation_of_mistake",
            "refs": ["Q0002", "Q0003", "Q0004"],
            "related_refs": []
          }
        ]
      },
      "aliases": null
    },
    {
      "concept_name": {
        "text": "Example workflow for an agentic AI system using n8n",
        "refs": ["Q0005", "Q0006", "Q0007", "Q0008", "Q0009", "Q0010"],
        "claims": [
          {
            "text": "A workflow can trigger an AI agent with memory, a chat model, and tools (e.g., Anthropic Claude, Jira, Slack) to automate onboarding tasks",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "correct_demonstration",
            "refs": ["Q0005", "Q0007"],
            "related_refs": []
          },
          {
            "text": "n8n provides a drag‑and‑drop interface to build such workflows without coding",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0009"],
            "related_refs": []
          },
          {
            "text": "The described workflow is an example of an agentic AI system",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "correct_demonstration",
            "refs": ["Q0010"],
            "related_refs": []
          }
        ]
      },
      "content": {
        "text": "When a new employee joins, the agent can create a Jira account, order a laptop, and add the employee to the appropriate Slack channel based on role.",
        "refs": ["Q0007", "Q0008"],
        "claims": [
          {
            "text": "The agent can branch logic (e.g., manager vs. individual contributor) to perform role‑specific actions",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "continuation",
            "refs": ["Q0007"],
            "related_refs": []
          }
        ]
      },
      "aliases": null
    },
    {
      "concept_name": {
        "text": "Low‑code alternatives for building agentic AI",
        "refs": ["Q0011"],
        "claims": [
          {
            "text": "Tools such as Zapier can also be used to build agentic AI systems",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "alternative_valid_approach",
            "refs": ["Q0011"],
            "related_refs": []
          }
        ]
      },
      "content": {
        "text": "These platforms allow integration of LLMs and external tools without writing code.",
        "refs": ["Q0011"],
        "claims": [
          {
            "text": "Low‑code platforms enable integration of LLMs and tools without coding",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "explanation_of_mistake",
            "refs": ["Q0011"],
            "related_refs": []
          }
        ]
      },
      "aliases": null
    },
    {
      "concept_name": {
        "text": "Difference between reactive chatbots and agentic AI",
        "refs": ["Q0012", "Q0013", "Q0014", "Q0015"],
        "claims": [
          {
            "text": "RAG chatbots are very reactive, providing answers based on retrieved documents",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0013"],
            "related_refs": []
          },
          {
            "text": "Agentic AI chatboards can use tools to act on user requests (e.g., query employee records, register leave) and maintain state",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "correct_demonstration",
            "refs": ["Q0015"],
            "related_refs": []
          }
        ]
      },
      "content": {
        "text": "Reactive chatbots answer questions; agentic AI can perform actions and maintain memory across interactions.",
        "refs": ["Q0012", "Q0015"],
        "claims": [
          {
            "text": "Agentic AI can augment chat with tool usage and stateful behavior",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "explanation_of_mistake",
            "refs": ["Q0015"],
            "related_refs": []
          }
        ]
      },
      "aliases": null
    }
  ],
